//! Copy-paste configuration snippets generated by the Add-site wizard (COLLAB.md Addenda 3, 5 and 7).
//!
//! Everything here is plain text for the operator to paste into their own infrastructure. The snippets are generated
//! from the site's real values, never from sample data, and each one is paired with an explicit limitation: the site is
//! not protected while the origin can still be reached directly (R-34) or while a serverless origin answers without the
//! shared secret. The HDD proxy itself is plain HTTP on loopback; TLS is terminated by Caddy, Cloudflare or nginx.

/// The loopback address the inspector listens on inside the HDD host.
pub const HDD_PROXY_LISTEN: &str = "127.0.0.1:8080";

/// The placeholder the operator replaces with the public address of the HDD host (the TLS terminator).
pub const PROXY_IP_PLACEHOLDER: &str = "<HDD_PROXY_IP>";

/// The env var name the generated Next.js middleware reads the origin secret from.
pub const ORIGIN_SECRET_ENV: &str = "HDD_ORIGIN_SECRET";

/// The secret header name suggested when a serverless site has not configured one yet.
pub const DEFAULT_ORIGIN_SECRET_HEADER: &str = "x-hdd-origin-secret";

/// Strip control characters from a value that is interpolated into a snippet.
///
/// The caller validates host names, origins and header names; this is defence in depth so a malformed value can never
/// inject a new line into a configuration file the operator pastes.
#[must_use]
pub fn one_line(value: &str) -> String {
    value
        .chars()
        .filter(|character| !character.is_control())
        .collect::<String>()
        .trim()
        .to_owned()
}

/// The Caddyfile that terminates TLS for `host` and forwards to the HDD inspector (DNS connection method).
#[must_use]
pub fn dns_caddyfile(host: &str) -> String {
    let host = one_line(host);
    format!(
        "# /etc/caddy/Caddyfile — generated by HDD for {host}\n\
         # Caddy terminates TLS for the public host and forwards the decrypted request to the HDD inspector.\n\
         {host} {{\n\
         \treverse_proxy {HDD_PROXY_LISTEN}\n\
         }}\n"
    )
}

/// The `cloudflared` configuration for the Cloudflare tunnel connection method.
#[must_use]
pub fn cloudflared_config(host: &str) -> String {
    let host = one_line(host);
    format!(
        "# ~/.cloudflared/config.yml — generated by HDD for {host}\n\
         # 1) cloudflared tunnel create hdd-demo\n\
         # 2) cloudflared tunnel route dns hdd-demo {host}\n\
         # 3) cloudflared tunnel run hdd-demo\n\
         tunnel: hdd-demo\n\
         credentials-file: /etc/cloudflared/hdd-demo.json\n\
         ingress:\n\
         \x20 - hostname: {host}\n\
         \x20   service: http://{HDD_PROXY_LISTEN}\n\
         \x20   originRequest:\n\
         \x20     httpHostHeader: {host}\n\
         \x20 - service: http_status:404\n"
    )
}

/// The public nginx server block that sits in front of HDD and terminates TLS (nginx connection method).
#[must_use]
pub fn nginx_public_front(host: &str) -> String {
    let host = one_line(host);
    format!(
        "# /etc/nginx/sites-available/{host} — generated by HDD\n\
         # Public nginx terminates TLS for the domain and forwards to the HDD inspector on loopback.\n\
         server {{\n\
         \tlisten 443 ssl http2;\n\
         \tserver_name {host};\n\
         \t# ssl_certificate / ssl_certificate_key: your existing certificate for {host}\n\
         \tlocation / {{\n\
         \t\tproxy_pass http://{HDD_PROXY_LISTEN};\n\
         \t\tproxy_set_header Host $host;\n\
         \t\tproxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n\
         \t\tproxy_set_header X-Forwarded-Proto $scheme;\n\
         \t\tproxy_http_version 1.1;\n\
         \t}}\n\
         }}\n"
    )
}

/// The `.htaccess` allowlist that locks an Apache origin down to the HDD proxy IP (R-34).
#[must_use]
pub fn origin_lockdown_htaccess() -> String {
    format!(
        "# .htaccess on the ORIGIN server — generated by HDD\n\
         # Refuse every request that did not come through the HDD proxy.\n\
         # Replace {PROXY_IP_PLACEHOLDER} with the public IP of the HDD host (the TLS terminator).\n\
         # Apache 2.4+ syntax; the mod_remoteip module must resolve the real client address correctly.\n\
         <RequireAll>\n\
         \x20   Require ip {PROXY_IP_PLACEHOLDER}\n\
         </RequireAll>\n"
    )
}

/// The nginx allowlist that locks an origin down to the HDD proxy IP (R-34).
#[must_use]
pub fn origin_lockdown_nginx() -> String {
    format!(
        "# Origin server (nginx) — generated by HDD\n\
         # Refuse every request that did not come through the HDD proxy.\n\
         # Replace {PROXY_IP_PLACEHOLDER} with the public IP of the HDD host (the TLS terminator).\n\
         location / {{\n\
         \tallow {PROXY_IP_PLACEHOLDER};\n\
         \tdeny all;\n\
         \t# ... your existing application handling stays here ...\n\
         }}\n"
    )
}

/// The Apache rewrite rule that enforces the shared origin secret header (serverless/origin alternative).
#[must_use]
pub fn origin_secret_htaccess(secret_header: &str) -> String {
    let header = one_line(secret_header);
    format!(
        "# .htaccess on the ORIGIN server — generated by HDD\n\
         # Enforce the shared origin secret for origins without a fixed IP (Vercel, Netlify, Render).\n\
         # The header value never belongs in this file: use an <ORIGIN_SECRET> placeholder in a\n\
         # server-side map, or prefer the Next.js middleware snippet for Vercel.\n\
         RewriteEngine On\n\
         RewriteCond %{{HTTP:{header}}} !^<ORIGIN_SECRET>$\n\
         RewriteRule ^ - [F,L]\n"
    )
}

/// The Next.js `middleware.ts` snippet that refuses requests without the origin secret (Addendum 5).
#[must_use]
pub fn nextjs_middleware(secret_header: &str) -> String {
    let header = one_line(secret_header);
    format!(
        "// middleware.ts — generated by HDD for a Vercel/Next.js origin.\n\
         // Refuses any request that did not arrive through the HDD proxy with the shared secret header.\n\
         // LIMITATION: the edge runtime has no constant-time string comparison available; the check\n\
         // below is a plain equality test. Use a long random secret (32+ bytes) and rotate it if leaked.\n\
         import {{ NextResponse }} from \"next/server\";\n\
         import type {{ NextRequest }} from \"next/server\";\n\
         \n\
         const SECRET = process.env.{ORIGIN_SECRET_ENV} ?? \"\";\n\
         const HEADER = \"{header}\";\n\
         \n\
         export function middleware(request: NextRequest): NextResponse {{\n\
         \x20 const supplied = request.headers.get(HEADER) ?? \"\";\n\
         \x20 if (SECRET.length > 0 && supplied !== SECRET) {{\n\
         \x20   return new NextResponse(\"Forbidden\", {{ status: 403 }});\n\
         \x20 }}\n\
         \x20 return NextResponse.next();\n\
         }}\n\
         \n\
         export const config = {{ matcher: \"/:path*\" }};\n"
    )
}

/// The explicit Edge Middleware alternative to the Next.js snippet (no `vercel.json` needed).
#[must_use]
pub fn edge_middleware_alternative(secret_header: &str) -> String {
    let header = one_line(secret_header);
    format!(
        "// middleware.ts (Edge Middleware alternative, no vercel.json needed) — generated by HDD.\n\
         // Vercel runs middleware.ts at the edge; pinning the runtime and matcher keeps static assets\n\
         // out of the check. The constant-time limitation of the edge runtime still applies.\n\
         import {{ NextResponse }} from \"next/server\";\n\
         import type {{ NextRequest }} from \"next/server\";\n\
         \n\
         const SECRET = process.env.{ORIGIN_SECRET_ENV} ?? \"\";\n\
         \n\
         export function middleware(request: NextRequest): NextResponse {{\n\
         \x20 const supplied = request.headers.get(\"{header}\") ?? \"\";\n\
         \x20 if (SECRET.length > 0 && supplied !== SECRET) {{\n\
         \x20   return new NextResponse(\"Forbidden\", {{ status: 403 }});\n\
         \x20 }}\n\
         \x20 return NextResponse.next();\n\
         }}\n\
         \n\
         export const config = {{\n\
         \x20 runtime: \"edge\",\n\
         \x20 matcher: \"/((?!_next/static|favicon.ico).*)\",\n\
         }};\n"
    )
}

/// The lock for a plain Node.js Vercel function that uses `module.exports`: one block pasted at the very end of the handler
/// file wraps whatever the file exports, so no existing line has to change.
#[must_use]
pub fn node_function_lock(secret_header: &str) -> String {
    let header = one_line(secret_header).to_ascii_lowercase();
    let lines = [
        "// Node function lock — generated by HDD. Paste this at the very END of your handler file".to_owned(),
        "// (the file Vercel runs, for example api/index.js). It wraps what the file exports: a request that did".to_owned(),
        "// not come through HDD is refused with 403. Nothing else in the file changes.".to_owned(),
        "// While HDD_ORIGIN_SECRET is not set the lock is off and the app answers everyone (not protected).".to_owned(),
        "(function hddLock() {".to_owned(),
        "  const crypto = require(\"crypto\");".to_owned(),
        format!("  const SECRET = process.env.{ORIGIN_SECRET_ENV} || \"\";"),
        "  const handler = module.exports;".to_owned(),
        "  if (typeof handler !== \"function\") {".to_owned(),
        "    throw new Error(\"HDD lock: this file must export a request handler function with module.exports\");".to_owned(),
        "  }".to_owned(),
        "  function fromHdd(req) {".to_owned(),
        format!("    const supplied = Buffer.from(String(req.headers[\"{header}\"] || \"\"));"),
        "    const expected = Buffer.from(SECRET);".to_owned(),
        "    return supplied.length === expected.length && crypto.timingSafeEqual(supplied, expected);".to_owned(),
        "  }".to_owned(),
        "  const locked = async function (req, res) {".to_owned(),
        "    if (SECRET.length > 0 && !fromHdd(req)) {".to_owned(),
        "      res.statusCode = 403;".to_owned(),
        "      return res.end(\"Forbidden: this site only answers through Hack Dev Defence (HDD).\");".to_owned(),
        "    }".to_owned(),
        "    return handler.apply(this, arguments);".to_owned(),
        "  };".to_owned(),
        "  Object.assign(locked, handler);".to_owned(),
        "  module.exports = locked;".to_owned(),
        "})();".to_owned(),
    ];
    let mut text = lines.join("\n");
    text.push('\n');
    text
}

/// The lock for a Node.js Vercel function written as an ES module (`export default`): a small helper file plus a two-line edit.
#[must_use]
pub fn node_esm_lock(secret_header: &str) -> String {
    let header = one_line(secret_header).to_ascii_lowercase();
    let lines = [
        "// Node ES module lock (file hdd-lock.js) — generated by HDD. Create this file next to your handler,".to_owned(),
        "// then write: import { lock } from \"./hdd-lock.js\";  export default lock(async (req, res) => { ... });".to_owned(),
        "import crypto from \"node:crypto\";".to_owned(),
        format!("const SECRET = process.env.{ORIGIN_SECRET_ENV} || \"\";"),
        "function fromHdd(req) {".to_owned(),
        format!("  const supplied = Buffer.from(String(req.headers[\"{header}\"] || \"\"));"),
        "  const expected = Buffer.from(SECRET);".to_owned(),
        "  return supplied.length === expected.length && crypto.timingSafeEqual(supplied, expected);".to_owned(),
        "}".to_owned(),
        "export function lock(handler) {".to_owned(),
        "  return async function (req, res) {".to_owned(),
        "    if (SECRET.length > 0 && !fromHdd(req)) {".to_owned(),
        "      res.statusCode = 403;".to_owned(),
        "      return res.end(\"Forbidden: this site only answers through Hack Dev Defence (HDD).\");".to_owned(),
        "    }".to_owned(),
        "    return handler(req, res);".to_owned(),
        "  };".to_owned(),
        "}".to_owned(),
    ];
    let mut text = lines.join("\n");
    text.push('\n');
    text
}

/// The front-door block, with `__HDD_SECRET_HEADER__` (lower-cased header name) and
/// `__HDD_ORIGIN_SECRET_ENV__` (the environment variable holding the secret) as the only placeholders.
///
/// A request that carries the secret header is served by the wrapped app. Every other request is forwarded to HDD
/// (`HDD_GATE_URL`) instead of the app, so HDD's Off / Monitor / Block decision applies to it; while the secret
/// variable is empty or unset the front door is off and the app answers everyone (stated in the first comment).
/// The block also keeps the reference's extra headers (`X-Forwarded-Host`, `X-Forwarded-Proto: https`,
/// `Accept-Encoding: identity`) because HDD needs them to see the visitor's real address and to avoid a
/// compressed body it cannot inspect.
const FRONT_DOOR_TEMPLATE: &str = r#"// Node front door — generated by HDD. Paste this at the very END of your handler file
// (the file Vercel runs, for example api/index.js). It wraps what the file exports: a request that
// carries HDD's secret header reaches the app unchanged, and every other request is forwarded to
// HDD first (HDD_GATE_URL) so HDD's Off / Monitor / Block decision applies before the app runs.
// The visitor keeps using this address. If HDD cannot be reached the request is refused with 503,
// never served uninspected, unless you set HDD_FAIL_OPEN=1: then the app answers directly while HDD is
// unreachable or HDD_GATE_URL is not set (the site stays usable, but those requests are NOT inspected).
// While HDD_ORIGIN_SECRET is empty or unset the front door is OFF and the app answers everyone (not
// protected). Nothing else in the file changes.
(function hddFrontDoor() {
  const crypto = require("crypto");
  const http = require("http");
  const https = require("https");

  const SECRET = process.env.__HDD_ORIGIN_SECRET_ENV__ || "";
  const FAIL_OPEN = /^(1|true|yes)$/i.test(process.env.HDD_FAIL_OPEN || "");
  const HOP = new Set([
    "connection", "keep-alive", "proxy-authenticate", "proxy-authorization", "te", "trailer",
    "transfer-encoding", "upgrade", "host", "content-length", "x-forwarded-for",
    "x-forwarded-host", "x-forwarded-proto", "x-real-ip", "forwarded", "x-hdd-gate-hop",
    "__HDD_SECRET_HEADER__",
  ]);
  const httpAgent = new http.Agent({ keepAlive: true, maxSockets: 16 });
  const httpsAgent = new https.Agent({ keepAlive: true, maxSockets: 16 });
  const ATTEMPTS = 5;
  const MAX_BODY = 1024 * 1024;
  const TIMEOUT_MS = 20000;

  function fromHdd(req) {
    const supplied = Buffer.from(String(req.headers["__HDD_SECRET_HEADER__"] || ""));
    const expected = Buffer.from(SECRET);
    return supplied.length === expected.length && crypto.timingSafeEqual(supplied, expected);
  }

  function parseGateUrl(value) {
    try {
      const url = new URL(value);
      return url.protocol === "http:" || url.protocol === "https:" ? url : null;
    } catch (error) { return null; }
  }

  const gateUrl = parseGateUrl(process.env.HDD_GATE_URL || "");

  // Optional: HDD_GATE_URL_FROM is a stable http(s) address that returns the CURRENT public URL of HDD as plain text
  // (for example a gist kept up to date by scripts/hdd-tunnel.mjs). It is read at most every 20 seconds, so a tunnel
  // that restarts with a new address heals without touching Vercel. HDD_GATE_URL stays the fallback.
  const gateFrom = parseGateUrl(process.env.HDD_GATE_URL_FROM || "");
  let discovered = { url: null, at: 0 };
  function fetchText(source) {
    return new Promise((resolveText, rejectText) => {
      const library = source.protocol === "https:" ? https : http;
      const target = new URL(source.href);
      target.searchParams.set("cb", String(Date.now()));
      const request = library.get(target, { timeout: 3000 }, (response) => {
        if (response.statusCode !== 200) { response.resume(); return rejectText(new Error("status " + response.statusCode)); }
        let text = "";
        response.setEncoding("utf8");
        response.on("data", (chunk) => { text += chunk; if (text.length > 2048) request.destroy(new Error("too large")); });
        response.on("end", () => resolveText(text));
      });
      request.on("error", rejectText);
      request.on("timeout", () => request.destroy(new Error("timeout")));
    });
  }
  async function currentGate() {
    if (!gateFrom) return gateUrl;
    if (discovered.url && Date.now() - discovered.at < 20000) return discovered.url;
    try {
      const parsed = parseGateUrl(String(await fetchText(gateFrom)).trim());
      if (parsed) discovered = { url: parsed, at: Date.now() };
    } catch (error) {
      console.error("front door: reading HDD_GATE_URL_FROM failed:", error && (error.code || error.message));
    }
    return discovered.url || gateUrl;
  }

  const esc = (value) => String(value).replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[character]));

  function refuse(res, code, headline, detail) {
    res.statusCode = code;
    res.setHeader("content-type", "text/html; charset=utf-8");
    res.setHeader("cache-control", "no-store");
    res.setHeader("x-content-type-options", "nosniff");
    res.end("<!doctype html><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>" + esc(headline) + "</title><style>body{font:16px/1.55 system-ui,Segoe UI,sans-serif;background:#f4f7fa;color:#14202b;display:grid;place-items:center;min-height:100vh;margin:0}main{max-width:520px;background:#fff;border:1px solid #d8e1e8;border-radius:14px;padding:28px;margin:16px}h1{font-size:22px;margin:0 0 8px}p{margin:.5em 0;color:#3d4f5f}</style><main><h1>" + esc(headline) + "</h1><p>" + esc(detail) + "</p><p>Protected by Hack Dev Defence (HDD)</p></main>");
  }

  async function readBody(req) {
    if (req.readable === false && req.body !== undefined) {
      const body = req.body;
      if (Buffer.isBuffer(body)) return body;
      if (typeof body === "string") return Buffer.from(body);
      const type = String(req.headers["content-type"] || "");
      return Buffer.from(/json/i.test(type) ? JSON.stringify(body) : new URLSearchParams(body).toString());
    }
    const chunks = [];
    let size = 0;
    for await (const chunk of req) {
      size += chunk.length;
      if (size > MAX_BODY) { const error = new Error("body too large"); error.code = "TOO_LARGE"; throw error; }
      chunks.push(chunk);
    }
    return Buffer.concat(chunks);
  }

  async function forward(req, res, target, serveDirectly) {
    let body;
    try { body = await readBody(req); } catch (error) {
      return refuse(res, error.code === "TOO_LARGE" ? 413 : 400, "Request refused", "The request could not be read.");
    }
    const headers = {};
    for (const [name, value] of Object.entries(req.headers)) if (!HOP.has(name.toLowerCase())) headers[name] = value;
    const client = String(req.headers["x-vercel-forwarded-for"] || req.headers["x-forwarded-for"] || "").split(",")[0].trim() || (req.socket && req.socket.remoteAddress) || "";
    // HDD (and any tunnel in front of it) routes by this Host, so it names HDD; the address the visitor typed travels in x-forwarded-host and x-hdd-gate-host.
    headers.host = target.host;
    if (req.headers.host) headers["x-hdd-gate-host"] = req.headers.host;
    if (req.headers.host) headers["x-forwarded-host"] = req.headers.host;
    headers["accept-encoding"] = "identity";
    headers["x-hdd-gate-hop"] = "1";
    headers["x-forwarded-proto"] = "https";
    if (client) headers["x-forwarded-for"] = client;
    if (body.length) headers["content-length"] = String(body.length);
    const replayable = req.method === "GET" || req.method === "HEAD";
    // One attempt resolves "retry" only when HDD did not answer and trying again cannot deliver the request twice:
    // a GET/HEAD, or a request that failed on a reused socket the other side had already closed (it never reached HDD).
    const attempt = (number) => new Promise((resolveAttempt) => {
      const destination = new URL(req.url || "/", target);
      const library = destination.protocol === "https:" ? https : http;
      const agent = destination.protocol === "https:" ? httpsAgent : httpAgent;
      headers.host = target.host;
      let settled = false;
      const done = (outcome) => { if (!settled) { settled = true; resolveAttempt(outcome); } };
      const out = library.request({
        protocol: destination.protocol, hostname: destination.hostname, port: destination.port,
        path: destination.pathname + destination.search, method: req.method, headers, timeout: TIMEOUT_MS, agent,
      }, (back) => {
        // Every answer from HDD carries a Ray ID. A 502/503/504 without one came from something in front of HDD (for example
        // a tunnel with no HDD behind it), so HDD was not reached: treat it like a connection failure.
        if (!back.headers["hdd-ray-id"] && (back.statusCode === 502 || back.statusCode === 503 || back.statusCode === 504)) {
          back.resume();
          console.error("front door: answer without a Ray ID (HDD not reached), status " + back.statusCode + " (attempt " + number + ")");
          return done(number < ATTEMPTS ? "retry" : "fail");
        }
        res.statusCode = back.statusCode || 502;
        for (const [name, value] of Object.entries(back.headers)) if (!HOP.has(name.toLowerCase())) res.setHeader(name, value);
        back.on("end", () => done("ok"));
        back.on("error", () => { res.destroy(); done("ok"); });
        back.pipe(res);
      });
      out.on("timeout", () => { out.destroy(); });
      out.on("error", (error) => {
        console.error("front door: HDD request failed (attempt " + number + "):", error && (error.code || error.message));
        if (res.headersSent) { res.destroy(); return done("ok"); }
        done(number < ATTEMPTS && (replayable || out.reusedSocket) ? "retry" : "fail");
      });
      out.end(body);
    });
    for (let number = 1; number <= ATTEMPTS; number++) {
      const outcome = await attempt(number);
      if (outcome === "ok") return;
      if (outcome === "fail") break;
      await new Promise((resolveWait) => setTimeout(resolveWait, 300 * number));
      if (gateFrom) { discovered.at = 0; target = (await currentGate()) || target; } // the address may have moved
    }
    discovered.at = 0; // the address may have changed: read it again on the next request
    if (res.headersSent) return;
    if (FAIL_OPEN) {
      // Opt-in: keep the site usable while HDD is unreachable. The body was already read, so hand it back to the app.
      console.error("front door: HDD unreachable, serving the request directly (HDD_FAIL_OPEN is on, NOT inspected)");
      req[Symbol.asyncIterator] = async function* replayBody() { yield body; };
      return serveDirectly();
    }
    refuse(res, 503, "Protection is unavailable", "This site only answers through Hack Dev Defence, and HDD could not be reached. The request was not served. Try again shortly.");
  }

  const handler = module.exports;
  if (typeof handler !== "function") {
    throw new Error("HDD front door: this file must export a request handler function with module.exports");
  }
  const wrapped = async function (req, res) {
    if (SECRET.length === 0) return handler.apply(this, arguments);
    if (fromHdd(req)) return handler.apply(this, arguments);
    const target = req.headers["x-hdd-gate-hop"] ? null : await currentGate();
    if (target) return forward(req, res, target, () => handler.apply(this, arguments));
    if (FAIL_OPEN) return handler.apply(this, arguments);
    res.statusCode = 403;
    res.setHeader("content-type", "text/plain; charset=utf-8");
    return res.end("Forbidden: this site only answers through Hack Dev Defence (HDD).");
  };
  Object.assign(wrapped, handler);
  module.exports = wrapped;
})();
"#;

/// The front door for a plain Node.js Vercel function that uses `module.exports`: one block pasted at the very END of the
/// handler file turns the address the visitor typed into a route that HDD inspects first. A request carrying HDD's secret
/// header reaches the app; every other request is forwarded to HDD (`HDD_GATE_URL`), refused with 403 when HDD cannot be
/// the destination, or answered with 503 when HDD is unreachable — the app is never served uninspected unless the owner opts
/// in with `HDD_FAIL_OPEN=1` (documented deviation: availability over inspection while HDD is down).
///
/// `secret_header` is used for the constant-time compare and is stripped from the forwarded headers.
#[must_use]
pub fn node_front_door(secret_header: &str) -> String {
    let header = one_line(secret_header).to_ascii_lowercase();
    FRONT_DOOR_TEMPLATE
        .replace("__HDD_SECRET_HEADER__", &header)
        .replace("__HDD_ORIGIN_SECRET_ENV__", ORIGIN_SECRET_ENV)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_snippets_never_contain_control_characters_from_input() {
        let hostile = "demo.example.com\n\ninjected: true";
        let caddy = dns_caddyfile(hostile);
        assert!(!caddy.contains("\n\ninjected"));
        assert!(caddy.contains("injected: true"));
    }

    #[test]
    fn the_dns_snippet_terminates_tls_and_forwards_to_loopback() {
        let snippet = dns_caddyfile("demo.example.com");
        assert!(snippet.contains("reverse_proxy 127.0.0.1:8080"));
        assert!(snippet.contains("demo.example.com"));
    }

    #[test]
    fn the_origin_lockdown_snippets_use_an_allowlist() {
        assert!(origin_lockdown_htaccess().contains("Require ip"));
        let nginx = origin_lockdown_nginx();
        assert!(nginx.contains("allow "));
        assert!(nginx.contains("deny all"));
    }

    #[test]
    fn the_vercel_snippets_read_the_secret_from_the_environment() {
        let next = nextjs_middleware("x-hdd-origin-secret");
        assert!(next.contains(ORIGIN_SECRET_ENV));
        assert!(next.contains("x-hdd-origin-secret"));
        assert!(next.contains("403"));
        let edge = edge_middleware_alternative("x-hdd-origin-secret");
        assert!(edge.contains("runtime: \"edge\""));
        assert!(edge.to_lowercase().contains("constant-time"));
        let node = node_function_lock("X-HDD-Origin-Secret");
        assert!(node.contains(ORIGIN_SECRET_ENV));
        assert!(
            node.contains("x-hdd-origin-secret"),
            "node lower-cases header names"
        );
        assert!(node.contains("timingSafeEqual"));
        assert!(node.contains("403"));
        assert!(
            node.contains("module.exports = locked"),
            "wraps the existing export"
        );
        let esm = node_esm_lock("X-HDD-Origin-Secret");
        assert!(esm.contains("export function lock"));
        assert!(esm.contains(ORIGIN_SECRET_ENV));
    }

    #[test]
    fn the_front_door_fixture_is_exactly_the_generated_snippet() {
        assert_eq!(
            node_front_door(DEFAULT_ORIGIN_SECRET_HEADER),
            include_str!("../../../docs/snippets/front-door.js"),
            "docs/snippets/front-door.js is the canonical paste block for the default header"
        );
    }

    #[test]
    fn the_front_door_lower_cases_the_secret_header_name() {
        let snippet = node_front_door("X-HDD-Origin-Secret");
        assert!(snippet.contains("x-hdd-origin-secret"));
        assert!(
            !snippet.contains("X-HDD-Origin-Secret"),
            "the emitted text never carries the caller's casing"
        );
        assert!(
            snippet.contains("\"x-hdd-origin-secret\","),
            "the lower-cased name is stripped from the forwarded headers"
        );
        assert!(
            snippet.contains("req.headers[\"x-hdd-origin-secret\"]"),
            "the lower-cased name is used for the constant-time compare"
        );
    }

    #[test]
    fn the_front_door_generates_the_required_behaviour_hooks() {
        let snippet = node_front_door(DEFAULT_ORIGIN_SECRET_HEADER);
        for needle in [
            "process.env.HDD_ORIGIN_SECRET",
            "process.env.HDD_GATE_URL",
            "empty or unset the front door is OFF",
            "x-hdd-gate-hop",
            "x-hdd-gate-host",
            "x-vercel-forwarded-for",
            "x-forwarded-for",
            "x-forwarded-proto",
            "accept-encoding",
            "timingSafeEqual",
            "keepAlive: true",
            "reusedSocket",
            "module.exports",
            "TOO_LARGE",
            "503",
            "Forbidden: this site only answers through Hack Dev Defence (HDD).",
        ] {
            assert!(
                snippet.contains(needle),
                "the front door must contain {needle}"
            );
        }
        assert!(
            !snippet.contains("__HDD_"),
            "every placeholder is replaced before the block is emitted"
        );
    }
}
